const ModbusRTU = global.get('modbusSerial');

if (!ModbusRTU) {
    node.error('Modulo modbus-serial nao encontrado em functionGlobalContext. Veja node-red/README.md.');
    return;
}

/*
=====================================
AJUSTE 1: dados de rede do CLP
=====================================

As variaveis de ambiente SOLDATECH_CLP_IP e
SOLDATECH_CLP_PORTA sobrescrevem o IP/porta
(uteis pra testar com um simulador sem mexer
no flow). Sem elas, usa o CLP real abaixo.
*/
const clpConfig = {
    ip: env.get('SOLDATECH_CLP_IP') || '10.200.7.154',
    port: Number(env.get('SOLDATECH_CLP_PORTA')) || 502,
    unitId: 1,
};

/*
=====================================
AJUSTE 2: mapa de memoria do CLP
=====================================

Regra confirmada empiricamente neste M221:
%Mn = coil Modbus n e %MWn = holding register n
(sem deslocamento).
*/
const clpRegs = {
    coils: {
        // %M10/%M11/%M12 em paralelo com %M1/%M2/%M3 (Rung0/1/2).
        jogCima: 10,      // %M10 -> Q0.0 sobe
        jogBaixo: 11,     // %M11 -> Q0.1 desce
        mesaStart: 12,    // %M12 -> Q0.2 mesa
        soldaOn: 3,       // AINDA NAO LIGADO NO CLP (sem rung para Q0.3/LED)
    },
    holdingRegisters: {
        zAlvoDecimm: 0,        // %MW0 - posicao Z alvo (decimos de mm)
        mesaAlvoDecigraus: 1,  // %MW1 - angulo alvo da mesa (decimos de grau)
    },
    /*
    Encoder do eixo Z: contador rapido %HSC0 (Rung6, entradas
    I0.0/I0.1) em palavra dupla, copiado no ladder (Rung7) com
    um bloco de operacao  %MD100 := %HSC0.VD  (32 bits).
    %MD100 = %MW100 (palavra baixa) + %MW101 (palavra alta)
    = holding registers 100 e 101.
    Se o %HSC0 voltar para palavra simples (%MW100 := %HSC0.V),
    troque palavras para 1.
    */
    encoderZ: {
        registro: 100,
        palavras: 2,
        palavraBaixaPrimeiro: true,
    },
};

global.set('clpConfig', clpConfig);
global.set('clpRegs', clpRegs);
global.set('clpEstado', { conectado: false, ultimaTentativa: 0 });

const client = new ModbusRTU();
client.setTimeout(2000);
global.set('clpClient', client);

async function lerEncoderZ() {
    const cfg = clpRegs.encoderZ;
    const resposta = await client.readHoldingRegisters(cfg.registro, cfg.palavras);
    const palavras = resposta.data;

    if (cfg.palavras === 1) {
        return palavras[0] > 32767 ? palavras[0] - 65536 : palavras[0];
    }

    const baixa = cfg.palavraBaixaPrimeiro ? palavras[0] : palavras[1];
    const alta = cfg.palavraBaixaPrimeiro ? palavras[1] : palavras[0];

    // (alta << 16) | baixa ja resulta em inteiro de 32 bits COM sinal.
    return (alta << 16) | baixa;
}

global.set('lerEncoderZ', lerEncoderZ);

/*
=====================================
CALIBRACAO DO ENCODER (contagem -> mm)
=====================================

Dois pontos marcados pelo operador na tela
("Marcar topo" no fim de curso de cima e
"Marcar base" no de baixo). Fica salva em
disco (context store 'arquivo', configurado
em settings.js) pra sobreviver a reinicios.
Marcar o topo de novo depois (ex.: CLP foi
desligado e o contador zerou em outro lugar)
desloca a base junto, mantendo a escala.
*/
const CHAVE_CALIBRACAO = 'calibracaoEncoderZ';

function lerCalibracao() {
    try {
        return global.get(CHAVE_CALIBRACAO, 'arquivo') || null;
    } catch (erro) {
        return global.get(CHAVE_CALIBRACAO) || null;
    }
}

function salvarCalibracao(calibracao) {
    try {
        global.set(CHAVE_CALIBRACAO, calibracao, 'arquivo');
    } catch (erro) {
        node.warn('Store "arquivo" indisponivel; calibracao do encoder so fica em memoria ate reiniciar o Node-RED.');
        global.set(CHAVE_CALIBRACAO, calibracao);
    }
}

function converterContagemParaMm(contagem, calibracao) {
    const c = calibracao;

    if (
        !c ||
        !Number.isFinite(c.contagemTopo) || !Number.isFinite(c.contagemBase) ||
        !Number.isFinite(c.zTopoMm) || !Number.isFinite(c.zBaseMm) ||
        c.contagemTopo === c.contagemBase
    ) {
        return null;
    }

    const fracao = (contagem - c.contagemBase) / (c.contagemTopo - c.contagemBase);
    return c.zBaseMm + fracao * (c.zTopoMm - c.zBaseMm);
}

global.set('calibracaoEncoder', {
    ler: lerCalibracao,
    salvar: salvarCalibracao,
    converter: converterContagemParaMm,
});

/*
=====================================
CONEXAO E RECONEXAO AUTOMATICA
=====================================

O modbus-serial NAO emite 'close' quando a
conexao cai por erro de rede (ex.: CLP trocou
de IP ou o cabo saiu) - so marca a porta como
fechada. Por isso, alem do 'close', um vigia
confere a porta a cada 1s, e o node de leitura
pede reconexao depois de 3 leituras sem resposta
seguidas (clpReconectar).
*/
let encerrado = false;
let reconectando = false;

function reconectar(motivo) {
    if (encerrado || reconectando) {
        return;
    }

    reconectando = true;
    global.set('clpEstado', { conectado: false, ultimaTentativa: Date.now() });
    node.warn('Conexao Modbus com o CLP perdida (' + motivo + '). Reconectando em 3s...');

    try {
        client.close(() => {});
    } catch (erro) {
        // porta ja fechada
    }

    setTimeout(conectar, 3000);
}

global.set('clpReconectar', reconectar);

function conectar() {
    if (encerrado) {
        return;
    }

    client.connectTCP(clpConfig.ip, { port: clpConfig.port })
        .then(async () => {
            if (encerrado) {
                try { client.close(() => {}); } catch (erro) { /* ignorar */ }
                return;
            }

            client.setID(clpConfig.unitId);

            /*
            Estado seguro ao conectar: os bits remotos
            (%M10/%M11/%M12) podem ter ficado LIGADOS de uma
            sessao anterior - o CLP mantem o ultimo valor
            escrito. Zera tudo ao conectar.
            */
            try {
                await client.writeCoil(clpRegs.coils.jogCima, false);
                await client.writeCoil(clpRegs.coils.jogBaixo, false);
                await client.writeCoil(clpRegs.coils.mesaStart, false);
                node.log('Estado remoto zerado ao conectar (jogCima/jogBaixo/mesaStart = OFF).');
            } catch (erroReset) {
                node.warn('Nao foi possivel zerar o estado remoto ao conectar: ' + erroReset.message);
            }

            reconectando = false;
            global.set('clpEstado', { conectado: true, ultimaTentativa: Date.now() });
            node.log('Conectado ao CLP via Modbus TCP em ' + clpConfig.ip + ':' + clpConfig.port);
        })
        .catch((erro) => {
            if (encerrado) {
                return;
            }

            reconectando = true;
            global.set('clpEstado', { conectado: false, ultimaTentativa: Date.now() });
            node.warn('Falha ao conectar ao CLP (' + clpConfig.ip + ':' + clpConfig.port + '): ' + erro.message + ' - nova tentativa em 3s.');
            setTimeout(conectar, 3000);
        });
}

client.on('close', () => reconectar('conexao fechada'));
client.on('error', (erro) => reconectar('erro: ' + (erro && erro.message)));

const vigia = setInterval(() => {
    const estadoAtual = global.get('clpEstado');

    if (!encerrado && !reconectando && estadoAtual && estadoAtual.conectado && !client.isOpen) {
        reconectar('porta fechada');
    }
}, 1000);

// Chamado no finalize (deploy/parada): nada desta instancia volta a conectar.
global.set('clpEncerrar', () => {
    encerrado = true;
    clearInterval(vigia);

    try {
        client.close(() => {});
    } catch (erro) {
        // ignorar
    }
});

conectar();

finalize:
const encerrar = global.get('clpEncerrar');

if (typeof encerrar === 'function') {
    encerrar();
}

global.set('clpEstado', { conectado: false, ultimaTentativa: Date.now() });

