const client = global.get('clpClient');
const regs = global.get('clpRegs');
const estado = global.get('clpEstado');
const corpo = msg.payload || {};
const idComando = corpo.idComando || null;

/*
Gesto da visao computacional: camera.html (celular,
GitHub Pages) publica { tipo:'GESTO_VISAO', gesto, origem,
timestamp, idEvento } neste mesmo topico; o Visao.py (camera
do PC) publica { tipo:'GESTO_VISAO', gesto } em
soldatech/visao/gesto. Os dois viram o comando GESTO_VISAO.
*/
const ehGesto = String(corpo.tipo || '').toUpperCase() === 'GESTO_VISAO';
const idEvento = corpo.idEvento || null;
const comando = ehGesto ? 'GESTO_VISAO' : String(corpo.comando || '').toUpperCase();
const dados = ehGesto
    ? { gesto: corpo.gesto, origem: corpo.origem || (msg.topic === 'soldatech/visao/gesto' ? 'CAMERA_PC' : 'VISAO'), timestamp: corpo.timestamp }
    : (corpo.dados || {});

function respostaOk(extra) {
    return {
        topic: 'soldatech/maquina/resposta',
        payload: Object.assign({ idComando, idEvento, tipo: 'COMANDO_OK', comando, timestamp: Date.now() }, extra || {}),
    };
}

function respostaErro(mensagem, codigo) {
    return {
        topic: 'soldatech/maquina/erro',
        payload: { idComando, idEvento, tipo: 'COMANDO_ERRO', comando, mensagem, codigo: codigo || 'ERRO_CLP', timestamp: Date.now() },
    };
}

// REGISTRAR_GESTO vem da camera DENTRO da simulacao 3D: so registra.
if (comando === 'REGISTRAR_GESTO') {
    node.send([respostaOk({ mensagem: 'Gesto registrado (simulacao 3D, maquina real nao acionada).' }), null]);
    return;
}

// PING nao depende do CLP: serve so para testar a ponte MQTT/Node-RED.
if (comando === 'PING') {
    node.send([respostaOk({ mensagem: 'pong' }), null]);
    return;
}

if (!regs || !client) {
    node.send([null, respostaErro('Node-RED ainda nao terminou de inicializar a conexao com o CLP.', 'CLP_NAO_INICIALIZADO')]);
    return;
}

if (!estado || !estado.conectado) {
    node.send([null, respostaErro('Node-RED sem conexao Modbus com o CLP no momento.', 'CLP_OFFLINE')]);
    return;
}

(async () => {
    try {
        let extraResposta = null;

        switch (comando) {
            case 'JOG_CIMA':
                await client.writeCoil(regs.coils.jogBaixo, false);
                await client.writeCoil(regs.coils.jogCima, true);
                break;

            case 'JOG_BAIXO':
                await client.writeCoil(regs.coils.jogCima, false);
                await client.writeCoil(regs.coils.jogBaixo, true);
                break;

            case 'JOG_PULSO': {
                // Pulso com duracao EXATA controlada aqui (nao pelo
                // tempo de clique no navegador).
                const direcaoPulso = String(dados.direcao || '').toUpperCase();
                const duracaoMs = Math.max(5, Math.min(2000, Number(dados.duracaoMs) || 30));
                const coilPulso = direcaoPulso === 'CIMA' ? regs.coils.jogCima : regs.coils.jogBaixo;

                if (direcaoPulso !== 'CIMA' && direcaoPulso !== 'BAIXO') {
                    throw new Error('JOG_PULSO precisa de dados.direcao CIMA ou BAIXO, recebido: ' + direcaoPulso);
                }

                await client.writeCoil(coilPulso, true);
                await new Promise((resolve) => setTimeout(resolve, duracaoMs));
                await client.writeCoil(coilPulso, false);
                break;
            }

            case 'JOG_PARAR':
                await client.writeCoil(regs.coils.jogCima, false);
                await client.writeCoil(regs.coils.jogBaixo, false);
                break;

            case 'MESA_START':
                await client.writeCoil(regs.coils.mesaStart, true);
                break;

            case 'MESA_STOP':
                await client.writeCoil(regs.coils.mesaStart, false);
                break;

            case 'SOLDA_ON':
                await client.writeCoil(regs.coils.soldaOn, true);
                break;

            case 'SOLDA_OFF':
                await client.writeCoil(regs.coils.soldaOn, false);
                break;

            case 'MOVER_PONTO': {
                const zMm = Number(dados.zMm);

                if (!Number.isFinite(zMm)) {
                    throw new Error('Ponto sem zMm valido: ' + JSON.stringify(dados));
                }

                flow.set('idComandoMovimentoPendente', idComando);
                await client.writeRegister(regs.holdingRegisters.zAlvoDecimm, Math.round(zMm * 10));

                if (dados.anguloMesaGraus !== undefined) {
                    node.warn('MOVER_PONTO pediu anguloMesaGraus=' + dados.anguloMesaGraus + ', mas o giro automatico da mesa para um angulo especifico ainda nao esta habilitado. Nada foi acionado na mesa.');
                }
                break;
            }

            case 'CALIBRAR_ENCODER_Z': {
                const referencia = String(dados.referencia || '').toUpperCase();
                const zMm = Number(dados.zMm);

                if ((referencia !== 'TOPO' && referencia !== 'BASE') || !Number.isFinite(zMm)) {
                    throw new Error('CALIBRAR_ENCODER_Z precisa de referencia TOPO ou BASE e zMm numerico.');
                }

                const calib = global.get('calibracaoEncoder');
                const contagem = await global.get('lerEncoderZ')();
                const atual = calib.ler() || {};
                const nova = Object.assign({}, atual);

                if (referencia === 'TOPO') {
                    if (Number.isFinite(atual.contagemTopo) && Number.isFinite(atual.contagemBase)) {
                        nova.contagemBase = atual.contagemBase + (contagem - atual.contagemTopo);
                    }

                    nova.contagemTopo = contagem;
                    nova.zTopoMm = zMm;
                } else {
                    nova.contagemBase = contagem;
                    nova.zBaseMm = zMm;
                }

                nova.atualizadoEm = Date.now();
                calib.salvar(nova);

                node.log('Encoder Z calibrado (' + referencia + '): contagem ' + contagem + ' = ' + zMm + ' mm. Calibracao: ' + JSON.stringify(nova));

                extraResposta = {
                    referencia,
                    contagem,
                    calibracao: nova,
                    calibrado: calib.converter(contagem, nova) !== null,
                };
                break;
            }

            case 'GESTO_VISAO': {
                // Mao aberta = START -> gira a mesa. Punho fechado = PAUSA -> para tudo.
                const gesto = String(dados.gesto || '').toUpperCase();

                if (gesto !== 'START' && gesto !== 'PAUSA') {
                    throw new Error('Gesto desconhecido: ' + gesto);
                }

                /*
                Um START atrasado (ex.: internet caiu e o broker
                entregou depois) nao pode ligar a mesa sozinho.
                PAUSA sempre e obedecido.
                */
                const enviadoEm = Number(dados.timestamp);
                const atrasoMs = Number.isFinite(enviadoEm) ? Math.abs(Date.now() - enviadoEm) : 0;

                if (gesto === 'START' && atrasoMs > 15000) {
                    node.warn('Gesto START ignorado: chegou com ' + Math.round(atrasoMs / 1000) + 's de atraso.');
                    node.send([null, respostaErro('START ignorado: chegou atrasado (' + Math.round(atrasoMs / 1000) + 's). Faca o gesto de novo.', 'GESTO_ATRASADO')]);
                    return;
                }

                if (gesto === 'START') {
                    await client.writeCoil(regs.coils.mesaStart, true);
                    extraResposta = { gesto, acao: 'MESA_START', mensagem: 'Mesa girando (gesto START).' };
                } else {
                    await client.writeCoil(regs.coils.jogCima, false);
                    await client.writeCoil(regs.coils.jogBaixo, false);
                    await client.writeCoil(regs.coils.mesaStart, false);
                    extraResposta = { gesto, acao: 'PARAR_TUDO', mensagem: 'Maquina parada (gesto PAUSA).' };
                }

                node.log('Gesto ' + gesto + ' (' + dados.origem + ') -> ' + extraResposta.acao);
                break;
            }

            case 'EMERGENCIA':
                // Parada pelo software: desliga todos os bits remotos.
                await client.writeCoil(regs.coils.jogCima, false);
                await client.writeCoil(regs.coils.jogBaixo, false);
                await client.writeCoil(regs.coils.mesaStart, false);
                break;

            default:
                node.send([null, respostaErro('Comando nao reconhecido pela ponte Node-RED: ' + comando, 'COMANDO_INVALIDO')]);
                return;
        }

        if (comando !== 'MOVER_PONTO') {
            node.send([respostaOk(extraResposta), null]);
        }
    } catch (erro) {
        if (/Port Not Open/i.test(erro.message)) {
            const reconectar = global.get('clpReconectar');

            if (typeof reconectar === 'function') {
                reconectar('comando ' + comando + ' com a porta fechada');
            }
        }

        node.send([null, respostaErro(erro.message, 'ERRO_MODBUS')]);
    }
})();

return null;

const client = global.get('clpClient');
const estado = global.get('clpEstado');
const lerEncoderZ = global.get('lerEncoderZ');
const calib = global.get('calibracaoEncoder');

if (!client || !lerEncoderZ || !calib || !estado || !estado.conectado) {
    // Sem CLP conectado: nao publica um STATUS inventado.
    return null;
}

// Leitura anterior ainda em andamento: pula este ciclo.
if (context.get('lendo')) {
    return null;
}

context.set('lendo', true);

(async () => {
    try {
        const contagem = await lerEncoderZ();
        context.set('errosSeguidos', 0);
        const agora = Date.now();
        const anterior = context.get('ultimaContagem');

        if (anterior !== contagem) {
            context.set('ultimaMudancaEm', agora);
        }

        context.set('ultimaContagem', contagem);

        const calibracao = calib.ler();
        const versaoCalibracao = calibracao ? calibracao.atualizadoEm : null;
        const calibracaoMudou = versaoCalibracao !== context.get('versaoCalibracaoEnviada');

        // Publica quando a posicao ou a calibracao muda, ou 1x/s como sinal de vida.
        const ultimoEnvio = context.get('ultimoEnvio') || 0;

        if (anterior === contagem && !calibracaoMudou && agora - ultimoEnvio < 1000) {
            return;
        }

        context.set('ultimoEnvio', agora);
        context.set('versaoCalibracaoEnviada', versaoCalibracao);

        const emMovimento = agora - (context.get('ultimaMudancaEm') || 0) < 300;
        const posicaoZMm = calib.converter(contagem, calibracao);

        const payload = {
            tipo: 'STATUS',
            estado: emMovimento ? 'EM MOVIMENTO' : 'PARADA',
            encoderZ: contagem,
            encoderCalibrado: posicaoZMm !== null,
            timestamp: agora,
        };

        if (posicaoZMm !== null) {
            payload.posicaoZMm = Math.round(posicaoZMm * 1000) / 1000;
        }

        node.send({ topic: 'soldatech/maquina/status', payload });
    } catch (erro) {
        const agora = Date.now();
        const errosSeguidos = (context.get('errosSeguidos') || 0) + 1;
        context.set('errosSeguidos', errosSeguidos);

        if (agora - (context.get('ultimoAvisoErro') || 0) > 10000) {
            context.set('ultimoAvisoErro', agora);
            node.warn('Erro ao ler o encoder do CLP: ' + erro.message);
        }

        // Porta fechada ou 3 leituras seguidas sem resposta: reconecta.
        if (/Port Not Open/i.test(erro.message) || errosSeguidos >= 3) {
            context.set('errosSeguidos', 0);
            const reconectar = global.get('clpReconectar');

            if (typeof reconectar === 'function') {
                reconectar('leitura do encoder: ' + erro.message);
            }
        }
    } finally {
        context.set('lendo', false);
    }
})();

return null;
